// Parse the incoming Telegram update and determine what action to take.
const u = $input.first().json;
let chatId, action, data = {};

if (u.callback_query) {
  chatId = String(u.callback_query.message.chat.id);
  const cb = u.callback_query.data || '';

  if (cb === 'menu')               action = 'send_menu';
  else if (cb === 'buscar_ticker') action = 'ask_ticker';
  else if (cb === 'buscar_ativos') action = 'send_buscar';
  else if (cb === 'setores')       action = 'send_sectors';
  else if (cb === 'ganhos')        { action = 'get_movers'; data = { type: 'gainers' }; }
  else if (cb === 'perdas')        { action = 'get_movers'; data = { type: 'losers'  }; }
  else if (cb === 'resumo_dia')    action = 'get_summary';
  else if (cb.startsWith('setor_'))   { action = 'get_sector'; data = { sector: cb.slice(6) }; }
  else if (cb.startsWith('analyze_')) { action = 'analyze';    data = { ticker: cb.slice(8) }; }
  else action = 'send_menu';

} else if (u.message) {
  chatId = String(u.message.chat.id);
  const txt = (u.message.text || '').trim().toUpperCase();
  const menuTriggers = ['/START', '/MENU', 'MENU', 'START', 'OI', 'OLA', 'OLOI', 'INICIO'];

  if (menuTriggers.includes(txt)) {
    action = 'send_menu';
  } else if (/^[A-Z]{1,5}(-[A-Z])?$/.test(txt)) {
    // Matches standard US ticker patterns: AAPL, MSFT, BRK-B
    action = 'analyze';
    data = { ticker: txt };
  } else {
    action = 'send_menu';
  }
} else {
  return [];
}

return [{ json: { chatId, action, data } }];

const res = $input.first().json;
const chatId = $node['Parse Input'].json.chatId;
const type = res.type;
const results = res.results || [];

const icon  = type === 'gainers' ? '📈' : '📉';
const title = type === 'gainers' ? 'PRINCIPAIS GANHOS' : 'PRINCIPAIS PERDAS';

let text = `<b>${icon} ${title} — ${res.date || ''}</b>\n\n`;
results.forEach((s, i) => {
  const sign = s.change_pct >= 0 ? '+' : '';
  text += `${i + 1}. <b>${s.ticker}</b>  $${s.price}  ${sign}${s.change_pct}%\n`;
});
text += '\n<i>Toque em um ativo para análise completa:</i>';

const keyboard = results.map(s => ([{
  text: `${s.ticker}  ${s.change_pct >= 0 ? '📈 +' : '📉 '}${s.change_pct}%`,
  callback_data: `analyze_${s.ticker}`
}]));
keyboard.push([{ text: '🔙 Voltar', callback_data: 'buscar_ativos' }]);

return [{ json: {
  chatId,
  text,
  replyMarkup: JSON.stringify({ inline_keyboard: keyboard })
} }];

const res = $input.first().json;
const chatId = $node['Parse Input'].json.chatId;
const sector = res.sector || 'Setor';
const results = res.results || [];

let text = `<b>🏣 ${sector}</b>\n\n`;
results.forEach((s, i) => {
  const chg = s.change_pct != null
    ? ` ${s.change_pct >= 0 ? '📈 +' : '📉 '}${s.change_pct}%`
    : '';
  text += `${i + 1}. <b>${s.ticker}</b>  $${s.price}${chg}\n`;
});
text += '\n<i>Toque em um ativo para análise completa:</i>';

const keyboard = results.map(s => ([{
  text: `${s.ticker}  $${s.price}${s.change_pct != null ? (s.change_pct >= 0 ? ' 📈' : ' 📉') : ''}`,
  callback_data: `analyze_${s.ticker}`
}]));
keyboard.push([
  { text: '🏣 Outros Setores', callback_data: 'setores' },
  { text: '🔙 Voltar',        callback_data: 'buscar_ativos' }
]);

return [{ json: {
  chatId,
  text,
  replyMarkup: JSON.stringify({ inline_keyboard: keyboard })
} }];

// Fetch gainers + losers in parallel and build a daily summary.
// Requires n8n >= 0.214 (uses $helpers.httpRequest).
const API = 'YOUR_API_URL';
const chatId = $json.chatId;

const [g, l] = await Promise.all([
  $helpers.httpRequest({ method: 'GET', url: `${API}/api/market/movers?type=gainers&limit=5` }),
  $helpers.httpRequest({ method: 'GET', url: `${API}/api/market/movers?type=losers&limit=5`  })
]);

const gainers = g.results || [];
const losers  = l.results || [];
const date    = g.date || new Date().toISOString().slice(0, 10);

let text = `<b>📋 RESUMO DO DIA — ${date}</b>\n\n`;

text += '<b>📈 Maiores Altas:</b>\n';
gainers.forEach((s, i) => {
  text += `${i + 1}. <b>${s.ticker}</b>  +${s.change_pct}%  $${s.price}\n`;
});

text += '\n<b>📉 Maiores Baixas:</b>\n';
losers.forEach((s, i) => {
  text += `${i + 1}. <b>${s.ticker}</b>  ${s.change_pct}%  $${s.price}\n`;
});

const replyMarkup = JSON.stringify({
  inline_keyboard: [[
    { text: '📊 Analisar Ativo', callback_data: 'buscar_ticker' },
    { text: '🔙 Menu',         callback_data: 'menu'          }
  ]]
});

return [{ json: { chatId, text, replyMarkup } }];
